import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] rating = new long[(int) n];
        for (int i = 0; i < rating.length; i++) rating[i] = Long.parseLong(next());

        long[] candy = new long[(int) n];
        Arrays.fill(candy, 1);
        for (int i = 1; i < n; i++) if (rating[i] > rating[i - 1]) candy[i] = candy[i - 1] + 1;
        for (int i = (int) n - 2; i >= 0; i--) if (rating[i] > rating[i + 1] && candy[i] <= candy[i + 1]) candy[i] = candy[i + 1] + 1;
        long total = 0;
        for (long x : candy) total += x;
        System.out.println(total);
    }
}
